/**
 * Client CRI bus routing for story audio (phone / TV / reverb).
 *
 * The client never filters a call itself: each ACB cue is authored with bus
 * sends, and glowing.acf gives those buses their DSP. The table is generated by
 * scripts/build-native-audio-bus-routing.py; see docs/NATIVE_AUDIO_BUS_ROUTING.md.
 * A cue that lists sends reaches only those buses, so a `bus_phone`-only cue has
 * no dry signal. Cues missing from the table keep the default MasterOut 1.0.
 */
import ROUTING from '../../data/nativeAudioBusRouting.json' with { type: 'json' }

export const NATIVE_AUDIO_ROUTING = ROUTING
/** StoryView SE rows with an empty acb column play from the first general sheet. */
export const DEFAULT_SE_CUE_SHEET = 'se_commu'
export const MASTER_OUT = 'MasterOut'

const PROFILES = Object.freeze(ROUTING.profiles.map(profile => Object.freeze({ ...profile })))
const VOICE_ROUTES = new Map()
for (const [profile, cues] of Object.entries(ROUTING.voice)) for (const cue of cues) VOICE_ROUTES.set(cue, Number(profile))

const stem = file => String(file || '').split(/[?#]/)[0].split('/').pop().replace(/\.[a-z0-9]+$/i, '')

/** Route of a voice by the file the player resolved (its stem is the ACB cue name). */
export function nativeVoiceRoute(file) {
  const profile = VOICE_ROUTES.get(decodeURIComponent(stem(file)))
  return profile == null ? null : PROFILES[profile]
}

/** Route of a sheet's cue. A sheet holding one routed cue answers for its only cue
 * (compiled bgm/ambience keep the sheet; ambience `_t` sheets name the cue without `_t`). */
export function nativeCueRoute(sheet, cue = null) {
  const cues = ROUTING.sheets[sheet]
  if (!cues) return null
  const names = Object.keys(cues)
  const name = cue && cues[cue] != null ? cue : (!cue && names.length === 1 ? names[0] : null)
  return name == null ? null : PROFILES[cues[name]]
}

export function nativeSeRoute(cue, sheet = null) {
  return nativeCueRoute(sheet || DEFAULT_SE_CUE_SHEET, cue)
}

const dB = linear => 20 * Math.log10(Math.max(linear, 1e-6))

// CRIWARE/32BandsEQ parameters come as [type, frequency, Q, linear gain] per band.
// Band type 2 is the ASR EQ peaking type (0 low shelf, 1 high shelf, 2 peaking).
const EQ_TYPES = Object.freeze({ 0: 'lowshelf', 1: 'highshelf', 2: 'peaking' })

function eqBands(params) {
  const bands = []
  for (let i = 0; i + 3 < params.length; i += 4) {
    const [type, frequency, q, gain] = params.slice(i, i + 4)
    if (!EQ_TYPES[type]) throw new RangeError(`unsupported CRI EQ band type ${type}`)
    bands.push({ type: EQ_TYPES[type], frequency, Q: q, gain: dB(gain) })
  }
  return bands
}

/** Web Audio stand-ins for the CRI DSPs; the parameters are the ACF values. */
export function describeNativeBus(name) {
  const bus = ROUTING.buses[name]
  if (!bus) throw new RangeError(`unknown native bus: ${name}`)
  const stages = []
  for (const fx of bus.fx) {
    if (fx.dsp === 'CRIWARE/Bandpass') {
      const [low, high] = fx.params
      stages.push({ type: 'highpass', frequency: low, Q: Math.SQRT1_2 }, { type: 'lowpass', frequency: high, Q: Math.SQRT1_2 })
    } else if (fx.dsp === 'CRIWARE/32BandsEQ') {
      stages.push(...eqBands(fx.params))
    } else if (fx.dsp === 'CRIWARE/Reverb') {
      const [reverbTimeMs, roomSize, preDelayMs, cofLow, cofHigh] = fx.params
      stages.push({ type: 'reverb', seconds: reverbTimeMs / 1000, roomSize, preDelay: preDelayMs / 1000, cofLow, cofHigh })
    } else {
      throw new RangeError(`unsupported CRI DSP ${fx.dsp}`)
    }
  }
  return { name, volume: bus.volume, sends: { ...bus.sends }, stages }
}

// Deterministic noise keeps the reverb tail identical between sessions.
function reverbImpulse(context, { seconds, preDelay }) {
  const rate = context.sampleRate
  const delay = Math.round(preDelay * rate)
  const length = delay + Math.max(1, Math.round(seconds * rate))
  const impulse = context.createBuffer(2, length, rate)
  let seed = 0x5eed
  for (let channel = 0; channel < 2; channel++) {
    const data = impulse.getChannelData(channel)
    for (let i = delay; i < length; i++) {
      seed = (seed * 1664525 + 1013904223) >>> 0
      // Reverb time is RT60: -60 dB (e^-6.9078) at `seconds`.
      data[i] = ((seed / 0xffffffff) * 2 - 1) * Math.exp(-6.9078 * (i - delay) / rate / seconds)
    }
  }
  return impulse
}

/** One bus's DSP chain, input → stages → bus volume → `output`. */
export function createNativeBusChain(context, name, output) {
  const description = describeNativeBus(name)
  const input = context.createGain()
  const nodes = [input]
  let tail = input
  for (const stage of description.stages) {
    if (stage.type === 'reverb') {
      const convolver = context.createConvolver()
      convolver.normalize = true
      convolver.buffer = reverbImpulse(context, stage)
      tail.connect(convolver)
      nodes.push(convolver)
      tail = convolver
      if (stage.cofHigh > 0) {
        const lowpass = context.createBiquadFilter()
        lowpass.type = 'lowpass'
        lowpass.frequency.value = stage.cofHigh
        tail.connect(lowpass)
        nodes.push(lowpass)
        tail = lowpass
      }
      continue
    }
    const filter = context.createBiquadFilter()
    filter.type = stage.type
    filter.frequency.value = stage.frequency
    filter.Q.value = stage.Q
    if (stage.gain != null) filter.gain.value = stage.gain
    tail.connect(filter)
    nodes.push(filter)
    tail = filter
  }
  const volume = context.createGain()
  volume.gain.value = description.volume * (description.sends[MASTER_OUT] ?? 0)
  tail.connect(volume)
  volume.connect(output)
  nodes.push(volume)
  return { input, nodes, dispose: () => { for (const node of nodes) { try { node.disconnect() } catch {} } } }
}
